// Binary Search Tree with insert, search, and in-order traversal
class BSTNode {
  constructor(val) { this.val = val; this.left = this.right = null; }
}

class BST {
  #root = null;

  insert(val) {                                   // O(log n) balanced, O(n) worst
    const node = new BSTNode(val);
    if (!this.#root) { this.#root = node; return; }
    let cur = this.#root;
    while (true) {
      if (val < cur.val) {
        if (!cur.left)  { cur.left  = node; return; }
        cur = cur.left;
      } else {
        if (!cur.right) { cur.right = node; return; }
        cur = cur.right;
      }
    }
  }

  search(val) {                                   // O(log n) balanced
    let cur = this.#root;
    while (cur) {
      if (val === cur.val) return true;
      cur = val < cur.val ? cur.left : cur.right;
    }
    return false;
  }

  // In-order → sorted ascending
  inOrder(node = this.#root, result = []) {
    if (!node) return result;
    this.inOrder(node.left, result);
    result.push(node.val);
    this.inOrder(node.right, result);
    return result;
  }
}

const bst = new BST();
[8, 3, 10, 1, 6, 14, 4, 7].forEach(v => bst.insert(v));
console.log(bst.search(6));    // true
console.log(bst.search(99));   // false
console.log(bst.inOrder());    // [1, 3, 4, 6, 7, 8, 10, 14]

// Min-Heap — array-based, O(log n) push/pop, O(1) peek
class MinHeap {
  #h = [];
  #parent = i => Math.floor((i - 1) / 2);
  #left   = i => 2 * i + 1;
  #right  = i => 2 * i + 2;

  push(val) {                                     // O(log n)
    this.#h.push(val);
    let i = this.#h.length - 1;
    while (i > 0 && this.#h[this.#parent(i)] > this.#h[i]) {
      [this.#h[this.#parent(i)], this.#h[i]] = [this.#h[i], this.#h[this.#parent(i)]];
      i = this.#parent(i);
    }
  }

  pop() {                                         // O(log n)
    if (this.#h.length === 1) return this.#h.pop();
    const min = this.#h[0];
    this.#h[0] = this.#h.pop();
    let i = 0;
    while (true) {
      let smallest = i;
      const l = this.#left(i), r = this.#right(i);
      if (l < this.#h.length && this.#h[l] < this.#h[smallest]) smallest = l;
      if (r < this.#h.length && this.#h[r] < this.#h[smallest]) smallest = r;
      if (smallest === i) break;
      [this.#h[i], this.#h[smallest]] = [this.#h[smallest], this.#h[i]];
      i = smallest;
    }
    return min;
  }

  peek() { return this.#h[0]; }                   // O(1)
  get size() { return this.#h.length; }
}

const heap = new MinHeap();
[5, 3, 8, 1, 9, 2].forEach(v => heap.push(v));
console.log(heap.peek());  // 1
console.log(heap.pop());   // 1
console.log(heap.pop());   // 2
console.log(heap.pop());   // 3

